/* ---------------------------------------------------------
   پروژکشن ساده برای نقشه جهان (equirectangular)
--------------------------------------------------------- */
const LON_MIN = -180, LON_MAX = 180, LAT_MIN = -58, LAT_MAX = 75;
const SCALE = 2.4;
const W = (LON_MAX - LON_MIN) * SCALE;
const H = (LAT_MAX - LAT_MIN) * SCALE;
const proj = (lon, lat) => [(lon - LON_MIN) * SCALE, (LAT_MAX - lat) * SCALE];
const ringToStr = (ring) => ring.map(([lon, lat]) => proj(lon, lat).join(",")).join(" ");

